#!/usr/bin/env python3
"""Generate the 16x16 pixel font atlas (RGBA PNG). Phase 35 + PRE-1 + UX-6.

Determinism: the glyph tables are static data in this file, so the output
is stable across runs and platforms. Re-run after editing this file (or
CJK_CHARSET) to refresh assets/textures/font.png.

UX-6 (font expansion 33 -> 392, the "A+" plan): the CJK set is pinned to a
source TTF. Every run
  1. verifies the TTF (SHA-256 + size + face count + SC face + version);
  2. re-rasterizes the LEGACY 33 glyphs (LEGACY_CJK_CELL) from the TTF and
     requires a BIT-EXACT match against the embedded table ("legacy
     self-check 33/33") - any Noto/parameter drift fails loudly instead of
     silently reusing a stale table (CRAFT-4 precedent);
  3. re-rasterizes the extended glyphs and either extends the auto table
     (CJK_FONT/CJK_CELL between the UX-6 markers) or fails on drift;
  4. checks the atlas top 512 rows pixel-identical to the pre-existing
     font.png (the legacy red line) before writing the 256x2080 file;
  5. emits the kCjkGlyphs initializer snippet (tools never touch src/).

Adding a character = append it to CJK_CHARSET and re-run this script: the
table, the PNG and the snippet update in one command, zero code changes.

Atlas layout (256x2080, 32px cells; 65 rows):
  - rows 4..15 are indexed by ASCII code: cell (c % 8, c // 8), so ASCII
    codes 32..126 keep the original c // 8 row indexing (cell 127 = DEL
    is dead, and since CRAFT-4 holds the 33rd legacy CJK glyph, 作);
  - rows 0..3 hold the first 32 legacy CJK glyphs: ASCII codes 0..31 are
    control characters that never render (src/ui/font.cpp maps them to
    '?'), so those 32 cells were dead transparent space (PRE-1);
  - rows 16..64 (cells 128..519) hold the EXTENDED CJK set: the glyphs of
    CJK_CHARSET that are not among the legacy 33, in codepoint order, the
    i-th one taking cell 128 + i (rows 16..60; rows 61..64 = headroom).
    The legacy 33 keep their cells 0..31 / 127, so every PRE-1 UV and all
    of rows 0..15 stay bit-identical (the top-512 red line, checked on
    every run);
  - each 16x16 glyph is drawn centered in its 32px cell (8px offset);
  - ink pixels are white with full alpha; everything else is transparent.

ASCII glyph data: the FONT table was extracted once (offline) from
DejaVu Sans Bold, em 16px, baseline at cell row 12 (descenders use rows
13..15), coverage threshold 128. 2 px strokes, monospace (the advance
is the full 16 px cell, see src/ui/font.cpp).

CJK glyph data: the CJK_FONT table was extracted from Noto Sans CJK SC
Regular (the 'SC' face, index 2, of the pinned NotoSansCJK-Regular.ttc),
em 16px: the rasterizer's line box (ascent 19 px, descent 5 px) is
windowed to its rows 5..20 (the PRE-1 placement that minimizes clipped
ink) and centered on the 16 px advance, coverage threshold >= 128. CJK
glyphs use the same 16 px monospace advance as ASCII (PRE-1: mixed text
keeps one advance per codepoint). The TTF is a TOOL-TIME input only -
the game build never needs it, same as the ASCII table.

The game (src/ui/font.cpp) maps a decoded UTF-8 codepoint to its cell
and reads the 16x16 sub-rect; unknown codepoints fall back to the '?'
glyph.
"""
import hashlib
import os
import struct
import zlib

W, H = 256, 2080  # UX-6: 65 rows (LEGACY_ROWS + 49 extended-CJK rows)
CELL = 32
GLYPH = 16
GLYPH_OFFSET = (CELL - GLYPH) // 2  # 8
LEGACY_ROWS = 16  # rows 0..15 = the pre-UX-6 256x512 atlas - RED LINE
LEGACY_H = LEGACY_ROWS * CELL  # 512
NEW_CJK_FIRST_CELL = 128  # first cell of row 16 (the extended CJK region)
NEW_CJK_MAX_CELL = 519  # last cell of the 65-row atlas (row 64)
OUT = os.path.join(os.path.dirname(__file__), "..", "assets",
                   "textures", "font.png")
SNIPPET_OUT = "/tmp/opencode/pipe3_s0/s160/kcjk_snippet.txt"

# UX-6 charset / legacy counts (pinned manifest sizes).
CHARSET_COUNT = 392  # len(CJK_CHARSET): unique, codepoint-sorted
LEGACY_COUNT = 33    # len(LEGACY_CJK_CELL): PRE-1 32 + CRAFT-4 作

# The pinned source font (UX-6: extraction is scripted + the source is
# pinned; a missing/mismatching file fails loudly, never a silent reuse
# of a stale table). Noto Sans CJK SC Regular lives at face index 2 of
# the 10-face TTC; the version string is "Version 2.004;...".
TTF_PATH = "/usr/share/fonts/noto-cjk/NotoSansCJK-Regular.ttc"
TTF_SHA256 = "b76b0433203017ca80401b2ee0dd69350349871c4b19d504c34dbdd80541690a"
TTF_SIZE = 19484784  # bytes, of the pinned file
TTC_FACE_COUNT = 10
SC_FACE_INDEX = 2
SC_FAMILY = "Noto Sans CJK SC"
SC_VERSION_PREFIX = "Version 2.004"

# PRE-1 rasterization parameters (em 16; the line box is windowed to its
# rows 5..20; a pixel is ink iff its coverage >= 128).
EM = 16
ASCENT, DESCENT = 19, 5  # pinned: font.getmetrics() must equal (19, 5)
LINE_BOX = ASCENT + DESCENT  # 24
WINDOW_TOP = 5  # top line-box row of the 16 px glyph window
