def rasterize_cjk(font, cp: int):
    """Rasterize ONE codepoint with the PRE-1 parameters: em 16, the line
    box windowed to rows WINDOW_TOP..WINDOW_TOP+15 (5..20), coverage
    threshold INK_THRESHOLD, ink placed at its font horizontal offset
    (bbox left) inside the 16 px advance. Returns 16 rows of 16 chars
    ('#' ink / '.' empty)."""
    ch = chr(cp)
    bbox = font.getbbox(ch)
    if bbox is None:
        raise ValueError("U+%04X: no glyph in the SC face" % cp)
    left, top, right, bottom = bbox
    mask = font.getmask(ch, mode="L")
    mw, mh = mask.size
    if (mw, mh) != (right - left, bottom - top):
        raise ValueError("U+%04X: mask %s != ink bbox %s"
                         % (cp, (mw, mh), bbox))
    out = []
    for cy in range(GLYPH):
        my = cy - (top - WINDOW_TOP)
        row = []
        for cx in range(GLYPH):
            mx = cx - left
            if 0 <= mx < mw and 0 <= my < mh:
                row.append("#" if mask.getpixel((mx, my)) >= INK_THRESHOLD
                           else ".")
            else:
                row.append(".")
        out.append("".join(row))
    return out


def verify_ttf() -> None:
    """Pin the source: missing file / wrong hash / wrong size / wrong face
    layout / wrong SC face / wrong version = named failure (no silent
    fallback to a stale table)."""
    if not os.path.exists(TTF_PATH):
        raise SystemExit("TTF missing: %s (expected SHA-256 %s...)"
                         % (TTF_PATH, TTF_SHA256[:12]))
    size = os.path.getsize(TTF_PATH)
    if size != TTF_SIZE:
        raise SystemExit("TTF size %d != pinned %d (%s)"
                         % (size, TTF_SIZE, TTF_PATH))
    sha = hashlib.sha256(open(TTF_PATH, "rb").read()).hexdigest()
    if sha != TTF_SHA256:
        raise SystemExit("TTF SHA-256 %s != pinned %s (%s)"
                         % (sha, TTF_SHA256, TTF_PATH))
    try:
        from fontTools.ttLib import TTCollection
    except ImportError:
        raise SystemExit("fontTools is required at tool time (pip fonttools)")
    tc = TTCollection(TTF_PATH)
    if len(tc.fonts) != TTC_FACE_COUNT:
        raise SystemExit("TTC face count %d != pinned %d"
                         % (len(tc.fonts), TTC_FACE_COUNT))
    sc = tc.fonts[SC_FACE_INDEX]["name"]
    family = sc.getDebugName(1)
    version = sc.getDebugName(5)
    if family != SC_FAMILY:
        raise SystemExit("TTC face %d family %r != %r"
                         % (SC_FACE_INDEX, family, SC_FAMILY))
    if not version.startswith(SC_VERSION_PREFIX):
        raise SystemExit("SC face version %r does not start with %r"
                         % (version, SC_VERSION_PREFIX))
    print("TTF pin OK: %s sha256 %s (%d B), %d faces, SC index %d, %s"
          % (os.path.basename(TTF_PATH), sha[:12], size, TTC_FACE_COUNT,
             SC_FACE_INDEX, version))


def write_table_section() -> None:
    """Rewrite the CJK_FONT/CJK_CELL auto section of THIS file from the
    current in-memory tables (kept in codepoint order)."""
    here = os.path.abspath(__file__)
    src = open(here).read()
    begin = src.index("# >>> UX-6 AUTO TABLE BEGIN")
    end = src.index("# <<< UX-6 AUTO TABLE END")
    font_lines = ["CJK_FONT = {"]
    for cp in sorted(CJK_FONT):
        rows = CJK_FONT[cp]
        font_lines.append("    0x%04X: (%s),"
                          % (cp, ", ".join("'%s'" % r for r in rows)))
    font_lines.append("}")
    cell_lines = ["CJK_CELL = {"]
    items = ["0x%04X: %d" % (cp, CJK_CELL[cp]) for cp in sorted(CJK_CELL)]
    for i in range(0, len(items), 6):
        cell_lines.append("    " + ", ".join(items[i:i + 6])
                          + ("," if i + 6 < len(items) else ""))
    cell_lines.append("}")
    table = "\n".join(font_lines) + "\n\n" + "\n".join(cell_lines) + "\n"
    src = src[:begin] + table + src[end:]
    with open(here, "w") as f:
        f.write(src)


def emit_snippet() -> None:
    """kCjkGlyphs initializer (codepoint order, explicit cells) -> the
    snippet file + stdout. tools/generate_*.py never touches src/; the
    snippet is pasted into src/ui/font.hpp by hand."""
    order = sorted(CJK_CELL)
    n_ext = len(order) - LEGACY_COUNT
    last = NEW_CJK_FIRST_CELL + n_ext - 1
    lines = ["// UX-6: the %d-entry CJK set (codepoint order). The legacy "
             "33 keep their" % len(order),
             "// PRE-1/CRAFT-4 cells (0..31, 127); the %d extended glyphs "
             "take cells" % n_ext,
             "// %d..%d in codepoint order (atlas rows 16..%d; rows 61..64 "
             "= headroom)." % (NEW_CJK_FIRST_CELL, last, last // 8)]
    lines.append("inline constexpr CjkGlyph kCjkGlyphs[%d] = {" % len(order))
    items = ["    {0x%04X, %d}" % (cp, CJK_CELL[cp]) for cp in order]
    for i in range(0, len(items), 5):
        lines.append(", ".join(items[i:i + 5])
                     + ("," if i + 5 < len(items) else ""))
    lines.append("};")
    snippet = "\n".join(lines) + "\n"
    with open(SNIPPET_OUT, "w") as f:
        f.write(snippet)
    print("snippet -> %s (%d entries)" % (SNIPPET_OUT, len(order)))
    print(snippet)


def main() -> None:
    # ---- charset invariants -------------------------------------------
    cps = [ord(c) for c in CJK_CHARSET]
    assert len(cps) == CHARSET_COUNT, "expected the %d-glyph charset" % CHARSET_COUNT
    assert cps == sorted(set(cps)), "charset must be unique + codepoint-sorted"
    assert all(0x7F < cp <= 0xFFFF for cp in cps), "BMP non-ASCII only"
    assert set(LEGACY_CJK_CELL) <= set(cps), "legacy set missing from charset"
    assert len(FONT) == 95, "expected ASCII 32..126"
    for code in range(32, 127):
        assert code in FONT, "missing glyph 0x%02x" % code

    # ---- TTF pin + rasterizer ------------------------------------------
    verify_ttf()
    try:
        from PIL import ImageFont
    except ImportError:
        raise SystemExit("Pillow is required at tool time (pip pillow)")
    font = ImageFont.truetype(TTF_PATH, size=EM, index=SC_FACE_INDEX)
    metrics = font.getmetrics()
    if metrics != (ASCENT, DESCENT):
        raise SystemExit("line box %s != pinned (%d, %d)"
                         % (metrics, ASCENT, DESCENT))
    print("metrics OK: ascent %d, descent %d (line box %d)"
          % (ASCENT, DESCENT, LINE_BOX))

    raster = {cp: rasterize_cjk(font, cp) for cp in cps}

    # ---- legacy self-check 33/33 (the drift gate) ------------------------
    bad = [cp for cp in sorted(LEGACY_CJK_CELL)
           if tuple(raster[cp]) != CJK_FONT.get(cp)]
    if bad:
        for cp in bad[:3]:
            print("legacy DRIFT U+%04X:" % cp)
            for g, e in zip(raster[cp], CJK_FONT.get(cp, [])):
                if g != e:
                    print("  got", g)
                    print("  exp", e)
        raise SystemExit("legacy self-check failed: %d/%d differ - TTF or "
                         "rasterizer drift, no output written"
                         % (len(bad), LEGACY_COUNT))
    print("legacy self-check %d/%d OK (bit-exact vs embedded table)"
          % (LEGACY_COUNT, LEGACY_COUNT))

    # ---- auto-table sync: extend (never drift-silently) ------------------
    new = [cp for cp in cps if cp not in LEGACY_CJK_CELL]
    extended, drifted = [], []
    for i, cp in enumerate(new):
        cell = NEW_CJK_FIRST_CELL + i
        if cp not in CJK_FONT or CJK_CELL.get(cp) != cell:
            extended.append(cp)
        elif CJK_FONT[cp] != tuple(raster[cp]):
            drifted.append(cp)
    if drifted:
        raise SystemExit("CJK_FONT drift on %d extended glyph(s), first: "
                         "%s - pinned TTF changed? no output written"
                         % (len(drifted),
                            " ".join("U+%04X" % c for c in drifted[:5])))
    if extended:
        for i, cp in enumerate(new):
            CJK_FONT[cp] = tuple(raster[cp])
            CJK_CELL[cp] = NEW_CJK_FIRST_CELL + i
        write_table_section()
        print("CJK_FONT table extended: +%d glyph(s) embedded (now %d "
              "entries)" % (len(extended), len(CJK_FONT)))
    else:
        print("CJK_FONT table unchanged (%d entries: %d legacy + %d extended)"
              % (len(CJK_FONT), LEGACY_COUNT, len(new)))

    # ---- table invariants (post-sync) ------------------------------------
    assert len(CJK_FONT) == len(cps) and set(CJK_FONT) == set(cps)
    assert set(CJK_CELL) == set(CJK_FONT)
    cells = list(CJK_CELL.values())
    assert len(set(cells)) == len(cells), "duplicate CJK atlas cell"
    for cp in sorted(CJK_FONT):
        cell = CJK_CELL[cp]
        assert cell <= NEW_CJK_MAX_CELL, "CJK cell %d out of the atlas" % cell
        if cp in LEGACY_CJK_CELL:
            assert cell == LEGACY_CJK_CELL[cp], "legacy cell re-celled"
        else:
            assert NEW_CJK_FIRST_CELL <= cell, \
                "extended cell below %d" % NEW_CJK_FIRST_CELL
    for code, glyph in FONT.items():
        assert len(glyph) == 16, "glyph 0x%02x row count" % code
        for r, row in enumerate(glyph):
            assert len(row) == 16, "glyph 0x%02x row %d width" % (code, r)
    for cp, glyph in CJK_FONT.items():
        assert len(glyph) == 16, "glyph 0x%04x row count" % cp
        for r, row in enumerate(glyph):
            assert len(row) == 16, "glyph 0x%04x row %d width" % (cp, r)

    # ---- canvas -----------------------------------------------------------
    px = [[(0, 0, 0, 0)] * W for _ in range(H)]
    for code, glyph in FONT.items():
        col, row = code % 8, code // 8
        for gy, line in enumerate(glyph):
            for gx, ch in enumerate(line):
                if ch == "#":
                    px[row * CELL + GLYPH_OFFSET + gy][
                        col * CELL + GLYPH_OFFSET + gx] = (255, 255, 255, 255)
    for cp in sorted(CJK_FONT):
        glyph = CJK_FONT[cp]
        cell = CJK_CELL[cp]
        col, row = cell % 8, cell // 8
        for gy, line in enumerate(glyph):
            for gx, ch in enumerate(line):
                if ch == "#":
                    px[row * CELL + GLYPH_OFFSET + gy][
                        col * CELL + GLYPH_OFFSET + gx] = (255, 255, 255, 255)

    # ---- top-512 red line: pixel-identical to the pre-existing atlas ------
    if not os.path.exists(OUT):
        raise SystemExit("existing %s missing - cannot verify the top-512 "
                         "red line" % OUT)
    ow, oh, orows = read_png(OUT)
    ncheck = min(LEGACY_H, oh)
    diff = 0
    for y in range(ncheck):
        for x in range(W):
            if orows[y][4 * x:4 * x + 4] != bytes(px[y][x]):
                diff += 1
                if diff <= 3:
                    print("top-512 DIFF at (%d,%d): old %s new %s"
                          % (x, y, orows[y][4 * x:4 * x + 4], px[y][x]))
    if diff:
        raise SystemExit("top-512 red line broken: %d px differ" % diff)
    print("top-512 self-check OK (%d px identical, existing atlas %dx%d)"
          % (W * ncheck, ow, oh))

    # ---- write + verify ----------------------------------------------------
    write_png(OUT, px, W, H)
    nsize = os.path.getsize(OUT)
    nmd5 = hashlib.md5(open(OUT, "rb").read()).hexdigest()
    vw, vh, vrows = read_png(OUT)
    assert (vw, vh) == (W, H), "written atlas size mismatch"
    for y in range(LEGACY_H):
        for x in range(W):
            assert vrows[y][4 * x:4 * x + 4] == bytes(px[y][x]), \
                "written top-512 px differ at (%d,%d)" % (x, y)
    print("wrote %s (%dx%d, %d bytes, md5 %s)" % (OUT, W, H, nsize, nmd5))

    # ---- kCjkGlyphs snippet (tools never touch src/) -----------------------
    emit_snippet()


if __name__ == "__main__":
    main()
